def compute(vars):
    old = vars["v1"]
    new = vars["v2"]

    if old > new:
        value = "30/9/2018"
    elif new > old:
        value = "30/9/2019"
    else:
        value = None

    return {
        "value": value,
        "trace": {
            "financial_assets_30_9_2018": old,
            "financial_assets_30_9_2019": new,
            "comparison": "larger" if old != new else "equal",
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
